using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Web.Script.Serialization;
using DogSC.Windows;

namespace DogSC.Replica {
 static class UpdateTests {
  static object Release(string tag,bool draft,string host="github.com",string digest=null){string name="dogsc-"+tag+"-setup-x64.exe";return new {tag_name=tag,draft=draft,assets=new[]{new {name=name,state="uploaded",browser_download_url="https://"+host+"/adrian147258/dogsc/releases/download/"+tag+"/"+name,digest=digest??"sha256:"+new string('a',64),size=4}}};}
  static void Require(bool value,string text){if(!value)throw new Exception(text);}
  public static void Run(){string log=Path.Combine(Media.Root,"bin","update-results.txt");try{var serializer=new JavaScriptSerializer();string json=serializer.Serialize(new[]{Release("v0.1.0-windows-beta.2",false),Release("v0.1.0-windows-beta.4",false),Release("v0.1.0-windows-beta.12",false),Release("v9.0.0-windows-beta.1",true),Release("v8.0.0-windows-beta.1",false,"evil.example"),Release("v7.0.0-windows-beta.1",false,"github.com","invalid")});var result=Updates.Find(json,"v0.1.0-windows-beta.3");Require(result!=null&&result.Tag=="v0.1.0-windows-beta.12","Version order, draft, origin or digest filtering failed");Require(Updates.Find(json,"v0.1.0-windows-beta.12")==null,"Equal version offered as an update");Require(Updates.Find(serializer.Serialize(new[]{Release("v0.1.0-windows",false)}),"v0.1.0-windows-beta.12")!=null,"Stable version must follow prerelease");string future=serializer.Serialize(new[]{Release("v0.1.0-windows-beta.4",false),Release("v0.1.0-windows-beta.5",false),Release("v0.1.0-windows-beta.6",true)});Require(Updates.Find(future,"v0.1.0-windows-beta.1").Tag=="v0.1.0-windows-beta.5","First beta must update directly to latest published beta");Require(Updates.Find(future,"v0.1.0-windows-beta.3").Tag=="v0.1.0-windows-beta.5","Installer beta must skip intermediate versions");Require(Updates.Find(future,"v0.1.0-windows-beta.5")==null,"Latest beta must not offer older builds");string file=Path.Combine(Media.Root,"bin","update-check-fixture.dat");File.WriteAllText(file,"test");try{string hash;using(var s=File.OpenRead(file))using(var sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(s)).Replace("-","").ToLowerInvariant();Updates.Verify(file,new UpdateInfo {Size=4,Digest=hash});bool rejected=false;try{Updates.Verify(file,new UpdateInfo {Size=4,Digest=new string('0',64)});}catch{rejected=true;}Require(rejected,"Corrupt update accepted");rejected=false;try{Updates.Verify(file,new UpdateInfo {Size=5,Digest=hash});}catch{rejected=true;}Require(rejected,"Incomplete update accepted");}finally{File.Delete(file);}File.WriteAllText(log,"PASS: first beta can find beta 5 directly, intermediate versions are skipped, no downgrade; version order, release origin and draft filtering; exact file size and SHA-256 reject corrupted downloads.\n");}catch(Exception ex){File.WriteAllText(log,"FAIL: "+ex);Environment.ExitCode=1;}}
 }
}
